import magic
import os
from pathlib import Path
from typing import Optional

ALLOWED_EXTENSIONS = {'.jpg', '.jpeg', '.png', '.gif', '.pdf', '.txt'}
ALLOWED_MIMETYPES = {'image/jpeg', 'image/png', 'image/gif', 'application/pdf', 'text/plain'}
MAX_FILE_SIZE = 10 * 1024 * 1024  # 10MB

def validate_file_extension(filename: str) -> bool:
    """EGRR_PATTERN: Validate file extension against whitelist."""
    if not filename:
        return False
    ext = Path(filename).suffix.lower()
    return ext in ALLOWED_EXTENSIONS

def validate_file_size(file_path: str | Path, max_size: int = MAX_FILE_SIZE) -> bool:
    """EGRR_PATTERN: Validate file size is within limit."""
    try:
        size = os.path.getsize(file_path)
        return size <= max_size
    except OSError:
        return False

def validate_file_content(file_path: str | Path) -> Optional[str]:
    """EGRR_PATTERN: Validate file content matches extension using magic bytes."""
    try:
        mime = magic.from_file(str(file_path), mime=True)
        if mime not in ALLOWED_MIMETYPES:
            return None
        return mime
    except Exception:
        return None

def validate_upload(filename: str, file_path: str | Path) -> tuple[bool, str]:
    """EGRR_PATTERN: Complete file upload validation."""
    # Check extension
    if not validate_file_extension(filename):
        return False, f'File extension not allowed. Allowed: {ALLOWED_EXTENSIONS}'

    # Check size
    if not validate_file_size(file_path):
        return False, f'File too large. Maximum size: {MAX_FILE_SIZE // (1024*1024)}MB'

    # Check content (magic bytes)
    mime = validate_file_content(file_path)
    if not mime:
        return False, 'File content does not match extension or is not allowed'

    # Cross-check extension matches content
    ext = Path(filename).suffix.lower()
    expected_mimes = {
        '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg',
        '.png': 'image/png', '.gif': 'image/gif',
        '.pdf': 'application/pdf', '.txt': 'text/plain'
    }
    if expected_mimes.get(ext) != mime:
        return False, 'File extension does not match content type'

    return True, 'Validation passed'
